{
  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "La résolution 2026-05-167, page 5, adopte expressément le règlement 645 sur l’occupation et l’entretien des bâtiments."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "La résolution 2026-05-175, dont l’intitulé cité figure page 12, demande page 14 la suspension du processus d’adoption et la révision du projet de règlement agroenvironnemental."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "Le dispositif figurant page 19 autorise la signature d’une modification à la convention de concession de la halte routière ajoutant une clause pour l’agrandissement du bâtiment."
    },
    {
      "item": "i04",
      "choice": "v2",
      "reason": "Le dispositif page 19 autorise explicitement la demande 2026-009 « par projet de résolution », sans la qualifier de second projet ni d’adoption finale."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "La résolution 2026-05-187 autorise page 20 le PIIA 2026-010 pour la reconstruction de la maison au 318, chemin de L’Anse-de-Roche."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "La résolution 2026-05-188 autorise expressément page 20 le PIIA 2026-008 pour la maison au 99, chemin du Fjord."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "La résolution 2026-05-189 autorise page 21 le PIIA 2026-007 pour ajouter des panneaux de verre au patio du 322, chemin de L’Anse de Roche et en faire une verrière trois saisons."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "La résolution 2026-05-190 autorise page 21 le PIIA 2026-006 pour l’agrandissement du patio au 295, chemin de L’Anse de Roche, les petits PIIA étant inclus."
    },
    {
      "item": "i09",
      "choice": "v1",
      "reason": "La résolution 2026-05-191 autorise page 22 la dérogation portant bien le numéro imprimé 20226-009, réduisant de huit à deux mètres la marge arrière du lot 4 700 841."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "La résolution 2026-05-192 autorise page 22 la dérogation 2026-011 réduisant de huit à 6,25 mètres la marge arrière sur le lot 4 701 026."
    },
    {
      "item": "i11",
      "choice": "absent",
      "reason": "La résolution 2026-05-180, page 16, accepte une offre de services d’estimation de Stantec, ce qui relève des marchés de services exclus du rappel malgré la mention du développement de la rue Dufour."
    },
    {
      "item": "i12",
      "choice": "absent",
      "reason": "Cette proposition reprend le même objet et la même résolution 2026-05-175 que l’item i02, sans étape distincte, et constitue donc un doublon non crédité."
    }
  ]
}
